INTROS = {
 'coconut-creek': "Coconut Creek calls itself the Butterfly Capital of the World, after Butterfly World in Tradewinds Park. The north Broward city mixes quiet neighborhoods with the Seminole Casino Coconut Creek and a growing Main Street district along Lyons Road.",
 'cooper-city': "Cooper City is a small, mostly residential city in southwest-central Broward with the motto \"Someplace Special.\" It is known for its parks, youth sports and family neighborhoods, with shops and services clustered along Griffin Road and Stirling Road.",
 'coral-springs': "Coral Springs is a planned city in northwest Broward, incorporated in 1963. It is known for its tree-lined streets, strict appearance codes, large park system and the Coral Springs Center for the Arts, with most businesses along University Drive, Sample Road and Atlantic Boulevard.",
 'dania-beach': "Dania Beach, incorporated in 1904, is the oldest city in Broward County. Next to Fort Lauderdale-Hollywood International Airport, it has a public beach and fishing pier, the Dania Pointe shopping district and a long stretch of marine businesses along the Dania Cut-Off Canal.",
 'davie': "Davie keeps its Old Florida, western roots, with horse trails and the Bergeron Rodeo Grounds, while also being home to Nova Southeastern University and college campuses in its education corridor. Businesses line University Drive, Davie Road and Griffin Road.",
 'deerfield-beach': "Deerfield Beach is Broward's northernmost beach city, on the Palm Beach County line. Visitors know it for the Deerfield Beach International Fishing Pier and Quiet Waters Park, and locals for the restaurants and shops along Hillsboro Boulevard and the beachfront.",
 'fort-lauderdale': "Fort Lauderdale is Broward's county seat and largest city, nicknamed the Venice of America for its canals. Las Olas Boulevard, the Riverwalk, Port Everglades and miles of beach make it the county's center for dining, boating, tourism and business.",
 'hallandale-beach': "Hallandale Beach sits in Broward's southeast corner on the Miami-Dade line. It is home to Gulfstream Park, a beachfront along A1A and a busy commercial strip on Hallandale Beach Boulevard and US 1.",
 'hillsboro-beach': "Hillsboro Beach is a small, mostly residential town on a narrow barrier island along A1A between Deerfield Beach and Pompano Beach. It is home to the historic Hillsboro Inlet Lighthouse.",
 'hollywood': "Hollywood was founded by developer Joseph W. Young and incorporated in 1925. Its Hollywood Beach Broadwalk, the ArtsPark at Young Circle and a walkable downtown make it one of Broward's best-known destinations for dining and the beach.",
 'lauderdale-by-the-sea': "Lauderdale-By-The-Sea is a small beach town known for Anglin's Fishing Pier and reefs close enough to the shore for snorkeling and diving. Its compact downtown is packed with casual restaurants and beach shops.",
 'lauderdale-lakes': "Lauderdale Lakes is a central Broward city along State Road 7 and Oakland Park Boulevard. It has a large Caribbean community, and many of its small businesses, restaurants and salons reflect it.",
 'lauderhill': "Lauderhill is a central Broward city with a large Caribbean community. Central Broward Park, home to an international cricket stadium, is here, along with a long run of restaurants and shops on State Road 7 and Oakland Park Boulevard.",
 'lazy-lake': "Lazy Lake is one of the smallest municipalities in Florida: a handful of homes around a lake, surrounded by Wilton Manors. It has no commercial district of its own.",
 'lighthouse-point': "Lighthouse Point is a residential boating community in northeast Broward, laced with canals that lead to the Intracoastal Waterway and the Hillsboro Inlet. Its shops and restaurants cluster along Federal Highway.",
 'margate': "Margate is a residential city in north-central Broward along US 441 and Atlantic Boulevard. Local shopping centers, family restaurants and service businesses serve its established neighborhoods.",
 'miramar': "Miramar is one of Broward's largest cities, in the southwest corner of the county along the Miami-Dade line. It mixes newer neighborhoods with business parks and corporate offices, and is home to the Miramar Cultural Center and Miramar Regional Park.",
 'north-lauderdale': "North Lauderdale is a compact residential city in central Broward, bordered by Tamarac, Margate and Fort Lauderdale's western edge. Most of its businesses are neighborhood services along McNab Road, Kimberly Boulevard and State Road 7.",
 'oakland-park': "Oakland Park, just north of Fort Lauderdale, has a growing Culinary Arts District with breweries, restaurants and food makers, along with long-running service businesses on Dixie Highway, Oakland Park Boulevard and Andrews Avenue.",
 'parkland': "Parkland is Broward's northwest corner, a quiet city of large lots, parks and highly rated schools on the edge of the Everglades and the Palm Beach County line. Most shopping is along Hillsboro Boulevard and State Road 7.",
 'pembroke-park': "Pembroke Park is a small town in south Broward near Hallandale Beach and Hollywood, with a mix of light industry, warehouses and residential communities.",
 'pembroke-pines': "Pembroke Pines is one of Broward's largest cities by population, stretching across the southwest of the county. It is home to C.B. Smith Park, the Pembroke Lakes Mall and long commercial corridors on Pines Boulevard and Flamingo Road.",
 'plantation': "Plantation is a central Broward city known for its tree canopy, Plantation Heritage Park and the Westfield Broward mall. Businesses concentrate along Broward Boulevard, University Drive and the Plantation Walk area.",
 'pompano-beach': "Pompano Beach is a northeast Broward beach city with a rebuilt fishing pier, a revitalized beachfront, the Festival Flea Market and a long tradition of fishing and boating near the Hillsboro Inlet.",
 'sea-ranch-lakes': "Sea Ranch Lakes is a tiny village along A1A between Lauderdale-By-The-Sea and Fort Lauderdale. Behind its gates is a small residential community; its shopping center fronts A1A.",
 'southwest-ranches': "Southwest Ranches, incorporated in 2000, is a rural town of large lots, horse properties, nurseries and farms in southwest Broward, between Davie, Weston and Pembroke Pines.",
 'sunrise': "Sunrise in west-central Broward is home to Sawgrass Mills, one of the largest outlet malls in the United States, and Amerant Bank Arena, home of the Florida Panthers. Its Sawgrass corridor is a major hub for offices and shopping.",
 'tamarac': "Tamarac is a residential city in west-central Broward with many established neighborhoods and active-adult communities. Local businesses line Commercial Boulevard, University Drive and McNab Road.",
 'west-park': "West Park is a small city in south Broward, incorporated in 2005, between Hollywood, Miramar and Pembroke Park. It is mostly residential, with neighborhood businesses along State Road 7 and Pembroke Road.",
 'weston': "Weston is a master-planned city on Broward's western edge at the Everglades, incorporated in 1996. It is known for its parks, lakes and family neighborhoods, with shopping centered on Weston Road and the Weston Town Center.",
 'wilton-manors': "Wilton Manors is known as the Island City because it is ringed by forks of the Middle River. Wilton Drive is its main street for dining and nightlife, and the city is home to one of the most visible LGBTQ communities in Florida.",
 'unincorporated-broward': "Unincorporated Broward covers neighborhoods that are not part of any city, such as Broadview Park and Roosevelt Gardens. Broward County provides their local services directly.",
}
cases = ' '.join(f"WHEN '{k}' THEN '{v.replace(chr(39), chr(39)*2)}'" for k, v in INTROS.items())
keys = ','.join(f"'{k}'" for k in INTROS)
print(f"UPDATE cities SET intro = CASE slug {cases} END WHERE slug IN ({keys}) AND (intro IS NULL OR intro = '')")
